"use client";

import type { ComponentProps, ReactNode } from "react";
import { CloudUpload } from "lucide-react";
import { useTranslations } from "@fuma-translate/react";
import {
  useUpload,
  useMultiUpload,
  type UseUploadOptions,
  type UseMultiUploadOptions,
  type UploadProgress,
  type MultiUploadFileState,
} from "@dimah-s3/react";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";
import {
  resolveStatusSlot,
  type AttachmentLayoutAliases,
  type StatusSlot,
} from "@/registry/dimah-s3-ui/lib/attachment";
import { Button } from "@/registry/dimah-s3-ui/components/ui/button";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/registry/dimah-s3-ui/components/ui/tooltip";
import { UploadStatusBlock } from "@/registry/dimah-s3-ui/components/dimah-s3/upload/upload-status-block";
import { useUploadToast, type UploadToastCtrl } from "@/registry/dimah-s3-ui/hooks/use-upload-toast";
import { useFileRejectToast } from "@/registry/dimah-s3-ui/hooks/use-file-reject-toast";

const EMPTY_PROGRESS: UploadProgress = { loaded: 0, total: 0, percent: 0 };
const EMPTY_FILES: MultiUploadFileState[] = [];

/** Props for {@link UploadButton}. Extends {@link UseUploadOptions} or {@link UseMultiUploadOptions}. */
export type UploadButtonProps = (UseUploadOptions | UseMultiUploadOptions) &
  AttachmentLayoutAliases & {
    className?: string;
    /** Button label. */
    label?: string;
    /** Custom button content. Replaces default icon + label. */
    children?: ReactNode;
    disabled?: boolean;
    tooltipText?: string;
    /** Show toasts during upload. @default true */
    toast?: boolean;
    /**
     * Inline status control.
     * - `true` (default): render below the button
     * - `false`: hide status
     * - `(node) => ReactNode`: wrap or relocate the status node
     */
    status?: StatusSlot;
    /**
     * Force multi-file mode. When omitted, multi mode is inferred from
     * `maxFiles > 1`.
     */
    multiple?: boolean;
    /** Button variant. @default "default" */
    variant?: ComponentProps<typeof Button>["variant"];
    /** Button size. @default "default" */
    size?: ComponentProps<typeof Button>["size"];
    /** Extra classes on the trigger button element. */
    buttonClassName?: string;
  };

type ButtonShellProps = AttachmentLayoutAliases & {
  className?: string;
  label?: string;
  children?: ReactNode;
  disabled?: boolean;
  tooltipText?: string;
  toast?: boolean;
  status?: StatusSlot;
  variant?: ComponentProps<typeof Button>["variant"];
  size?: ComponentProps<typeof Button>["size"];
  buttonClassName?: string;
};

function UploadButtonSingle({
  className,
  label,
  children,
  disabled,
  tooltipText,
  toast: enableToast = true,
  status: statusSlot = true,
  variant = "default",
  size = "default",
  buttonClassName,
  attachmentSize,
  attachmentOrientation,
  ...options
}: ButtonShellProps & UseUploadOptions) {
  const t = useTranslations();
  const ctrl = useUpload({
    ...options,
    disabled,
    noDrag: true,
    noClick: true,
    noKeyboard: true,
  });
  const canPause = options.uploadStore != null && options.uploadStore !== false;
  const isDisabled = disabled || ctrl.isUploading;

  const toastCtrl: UploadToastCtrl = {
    mode: "single",
    phase: ctrl.phase,
    fileInfo: ctrl.fileInfo,
    progress: ctrl.progress,
    error: ctrl.error,
    cancel: ctrl.cancel,
  };
  useUploadToast(toastCtrl, enableToast);
  useFileRejectToast(ctrl.fileRejections, enableToast);

  const statusNode =
    statusSlot === false ? null : (
      <UploadStatusBlock
        mode="single"
        phase={ctrl.phase}
        progress={ctrl.progress}
        error={ctrl.error}
        fileInfo={ctrl.fileInfo}
        onCancel={ctrl.cancel}
        onPause={canPause ? ctrl.detach : undefined}
        size={attachmentSize}
        orientation={attachmentOrientation}
      />
    );
  const status = resolveStatusSlot(statusSlot, statusNode);

  const buttonLabel = label ?? t("Upload file", { note: "button" });
  const buttonContent = children ?? (
    <>
      <CloudUpload data-icon="inline-start" />
      {buttonLabel}
    </>
  );

  const button = (
    <Button
      variant={variant}
      size={size}
      className={buttonClassName}
      disabled={isDisabled}
      onClick={ctrl.open}
    >
      {buttonContent}
    </Button>
  );

  return (
    <div className={cn("inline-flex flex-col gap-2", className)}>
      <div className="inline-flex items-center gap-2">
        <input {...ctrl.getInputProps()} />
        {tooltipText ? (
          <Tooltip>
            <TooltipTrigger render={button} />
            <TooltipContent>{tooltipText}</TooltipContent>
          </Tooltip>
        ) : (
          button
        )}
      </div>
      {status}
    </div>
  );
}

function UploadButtonMulti({
  className,
  label,
  children,
  disabled,
  tooltipText,
  toast: enableToast = true,
  status: statusSlot = true,
  variant = "default",
  size = "default",
  buttonClassName,
  attachmentSize,
  attachmentOrientation,
  ...options
}: ButtonShellProps & UseMultiUploadOptions) {
  const t = useTranslations();
  const ctrl = useMultiUpload({
    ...options,
    disabled,
    noDrag: true,
    noClick: true,
    noKeyboard: true,
  });
  const canPause = options.uploadStore != null && options.uploadStore !== false;
  const isDisabled = disabled || ctrl.isUploading;

  const toastCtrl: UploadToastCtrl = {
    mode: "multi",
    phase: ctrl.phase,
    files: ctrl.files,
    totalProgress: ctrl.totalProgress,
    error: ctrl.error,
    cancel: ctrl.cancel,
  };
  useUploadToast(toastCtrl, enableToast);
  useFileRejectToast(ctrl.fileRejections, enableToast);

  const statusNode =
    statusSlot === false ? null : (
      <UploadStatusBlock
        mode="multi"
        phase={ctrl.phase}
        files={ctrl.files ?? EMPTY_FILES}
        totalProgress={ctrl.totalProgress ?? EMPTY_PROGRESS}
        error={ctrl.error}
        onCancel={ctrl.cancel}
        onPause={canPause ? ctrl.detach : undefined}
        size={attachmentSize}
        orientation={attachmentOrientation}
      />
    );
  const status = resolveStatusSlot(statusSlot, statusNode);

  const buttonLabel = label ?? t("Upload files", { note: "button" });
  const buttonContent = children ?? (
    <>
      <CloudUpload data-icon="inline-start" />
      {buttonLabel}
    </>
  );

  const button = (
    <Button
      variant={variant}
      size={size}
      className={buttonClassName}
      disabled={isDisabled}
      onClick={ctrl.open}
    >
      {buttonContent}
    </Button>
  );

  return (
    <div className={cn("inline-flex flex-col gap-2", className)}>
      <div className="inline-flex items-center gap-2">
        <input {...ctrl.getInputProps()} />
        {tooltipText ? (
          <Tooltip>
            <TooltipTrigger render={button} />
            <TooltipContent>{tooltipText}</TooltipContent>
          </Tooltip>
        ) : (
          button
        )}
      </div>
      {status}
    </div>
  );
}

export function UploadButton({ multiple, ...props }: UploadButtonProps) {
  const isMulti =
    multiple === true || ((props as UseMultiUploadOptions).maxFiles ?? 1) > 1;

  if (isMulti) {
    return (
      <UploadButtonMulti
        {...(props as ButtonShellProps & UseMultiUploadOptions)}
      />
    );
  }

  return (
    <UploadButtonSingle {...(props as ButtonShellProps & UseUploadOptions)} />
  );
}

"use client";

import { formatFileSize } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { formatEta, useFormatDimahError } from "@dimah-s3/react";
import type {
  DimahS3Error,
  UploadFileInfo,
  UploadPhase,
  UploadProgress,
} from "@dimah-s3/react";
import { FileAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/attachment/file-attachment";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/attachment/status-attachment";
import type { AttachmentLayoutProps } from "@/registry/dimah-s3-ui/lib/attachment";

export type UploadStatusProps = AttachmentLayoutProps & {
  phase: UploadPhase;
  progress: UploadProgress;
  error: DimahS3Error | null;
  fileInfo: UploadFileInfo | null;
  onCancel?: () => void;
  /** When set (typically with an `uploadStore`), shows a pause control. */
  onPause?: () => void;
  className?: string;
};

export function UploadStatus({
  phase,
  progress,
  error,
  fileInfo,
  onCancel,
  onPause,
  size,
  orientation,
  className,
}: UploadStatusProps) {
  const t = useTranslations();
  const formatError = useFormatDimahError();
  const errorText = error ? formatError(error) : null;
  const layout = { size, orientation, className };

  if (phase === "idle") return null;

  if (phase === "uploading" && fileInfo) {
    const eta =
      progress.speed && progress.total
        ? formatEta(progress.total - progress.loaded, progress.speed)
        : null;

    return (
      <FileAttachment
        state="uploading"
        fileName={fileInfo.name}
        fileSize={fileInfo.size}
        fileType={fileInfo.type}
        previewUrl={fileInfo.previewUrl}
        percent={progress.percent}
        description={
          eta ? `${formatFileSize(fileInfo.size)} · ${eta}` : undefined
        }
        onCancel={onCancel}
        onPause={onPause}
        {...layout}
      />
    );
  }

  if (phase === "success" && fileInfo) {
    return (
      <FileAttachment
        state="done"
        fileName={fileInfo.name}
        fileSize={fileInfo.size}
        fileType={fileInfo.type}
        previewUrl={fileInfo.previewUrl}
        {...layout}
      />
    );
  }

  if (phase === "error") {
    if (fileInfo) {
      return (
        <FileAttachment
          state="error"
          fileName={fileInfo.name}
          fileSize={fileInfo.size}
          fileType={fileInfo.type}
          previewUrl={fileInfo.previewUrl}
          error={errorText}
          {...layout}
        />
      );
    }

    return (
      <StatusAttachment
        state="error"
        title={t("Upload failed", { note: "status" })}
        description={errorText ?? undefined}
        {...layout}
      />
    );
  }

  if (phase === "validating" || phase === "presigning") {
    if (fileInfo) {
      return (
        <FileAttachment
          state="processing"
          fileName={fileInfo.name}
          fileSize={fileInfo.size}
          fileType={fileInfo.type}
          previewUrl={fileInfo.previewUrl}
          description={t("Preparing…", { note: "upload status" })}
          {...layout}
        />
      );
    }

    return (
      <StatusAttachment
        state="processing"
        title={t("Preparing…", { note: "upload status" })}
        {...layout}
      />
    );
  }

  return null;
}

"use client";

import { XIcon } from "lucide-react";
import { useTranslations } from "@fuma-translate/react";
import { formatEta, useFormatDimahError } from "@dimah-s3/react";
import type {
  DimahS3Error,
  UploadProgress,
  MultiUploadFileState,
  MultiUploadPhase,
} from "@dimah-s3/react";
import { FileAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/attachment/file-attachment";
import { StatusAttachment } from "@/registry/dimah-s3-ui/components/dimah-s3/attachment/status-attachment";
import { AttachmentAction } from "@/registry/dimah-s3-ui/components/ui/attachment";
import type { AttachmentLayoutProps, AttachmentState } from "@/registry/dimah-s3-ui/lib/attachment";
import {
  Progress,
  ProgressLabel,
  ProgressValue,
} from "@/registry/dimah-s3-ui/components/ui/progress";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

export type MultiUploadStatusProps = AttachmentLayoutProps & {
  phase: MultiUploadPhase;
  files: MultiUploadFileState[];
  totalProgress: UploadProgress;
  error: DimahS3Error | null;
  onCancel?: () => void;
  className?: string;
};

export function MultiUploadStatus({
  phase,
  files,
  totalProgress,
  error,
  onCancel,
  size,
  orientation,
  className,
}: MultiUploadStatusProps) {
  const t = useTranslations();
  const formatError = useFormatDimahError();
  const errorText = error ? formatError(error) : null;
  const layout = { size, orientation };

  if (phase === "idle") return null;

  if (phase === "uploading") {
    const eta =
      totalProgress.speed && totalProgress.total
        ? formatEta(
            totalProgress.total - totalProgress.loaded,
            totalProgress.speed,
          )
        : null;

    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        <div className="flex w-full items-center gap-1.5">
          <Progress value={totalProgress.percent} className="flex-1">
            <ProgressLabel>
              {t("{done}/{total} files", {
                note: "upload progress",
                variables: {
                  done: String(
                    files.filter((f) => f.status === "success").length,
                  ),
                  total: String(files.length),
                },
              })}
              {eta ? (
                <span className="font-normal text-dimah-s3-muted-foreground">
                  {" "}
                  · {eta}
                </span>
              ) : null}
            </ProgressLabel>
            <ProgressValue />
          </Progress>
          {onCancel ? (
            <AttachmentAction
              className="shrink-0"
              aria-label={t("Cancel", { note: "upload control" })}
              onClick={(e) => {
                e.stopPropagation();
                onCancel();
              }}
            >
              <XIcon />
            </AttachmentAction>
          ) : null}
        </div>
        <FileList files={files} {...layout} />
      </div>
    );
  }

  if (phase === "success") {
    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        <StatusAttachment
          state="done"
          title={t("All {count} file(s) uploaded", {
            note: "status",
            variables: { count: String(files.length) },
          })}
          {...layout}
        />
        <FileList files={files} {...layout} />
      </div>
    );
  }

  if (phase === "error") {
    return (
      <div className={cn("flex w-full flex-col gap-2", className)}>
        <StatusAttachment
          state="error"
          title={t("Upload failed", { note: "status" })}
          description={errorText ?? undefined}
          {...layout}
        />
        {files.length > 0 ? <FileList files={files} {...layout} /> : null}
      </div>
    );
  }

  if (phase === "validating") {
    return (
      <StatusAttachment
        state="processing"
        title={t("Validating…", { note: "upload status" })}
        className={className}
        {...layout}
      />
    );
  }

  return null;
}

function fileAttachmentState(
  status: MultiUploadFileState["status"],
): AttachmentState {
  switch (status) {
    case "pending":
      return "idle";
    case "uploading":
      return "uploading";
    case "error":
      return "error";
    case "success":
      return "done";
  }
}

function FileList({
  files,
  size,
  orientation,
}: AttachmentLayoutProps & { files: MultiUploadFileState[] }) {
  return (
    <div className="flex w-full flex-col gap-2">
      {files.map((f) => (
        <FileAttachment
          key={f.id}
          state={fileAttachmentState(f.status)}
          fileName={f.fileName}
          fileSize={f.fileSize}
          fileType={f.fileType}
          previewUrl={f.previewUrl}
          percent={f.progress.percent}
          error={f.error}
          size={size}
          orientation={orientation}
        />
      ))}
    </div>
  );
}

"use client";

import type {
  DimahS3Error,
  UploadFileInfo,
  UploadPhase,
  UploadProgress,
  MultiUploadFileState,
  MultiUploadPhase,
} from "@dimah-s3/react";
import { UploadStatus } from "@/registry/dimah-s3-ui/components/dimah-s3/upload/upload-status";
import { MultiUploadStatus } from "@/registry/dimah-s3-ui/components/dimah-s3/upload/multi-upload-status";
import type { AttachmentLayoutProps } from "@/registry/dimah-s3-ui/lib/attachment";

export type UploadStatusBlockProps = AttachmentLayoutProps &
  (
    | {
        mode: "single";
        phase: UploadPhase;
        progress: UploadProgress;
        error: DimahS3Error | null;
        fileInfo: UploadFileInfo | null;
        onCancel?: () => void;
        onPause?: () => void;
      }
    | {
        mode: "multi";
        phase: MultiUploadPhase;
        files: MultiUploadFileState[];
        totalProgress: UploadProgress;
        error: DimahS3Error | null;
        onCancel?: () => void;
        onPause?: () => void;
      }
  );

export function UploadStatusBlock(props: UploadStatusBlockProps) {
  const { size, orientation } = props;
  const layout = { size, orientation };

  if (props.mode === "multi" && props.files.length === 1) {
    const f = props.files[0];
    return (
      <UploadStatus
        phase={props.phase}
        progress={f.progress}
        error={f.error ?? props.error}
        fileInfo={{
          name: f.fileName,
          size: f.fileSize,
          type: f.fileType,
          previewUrl: f.previewUrl,
        }}
        onCancel={props.onCancel}
        onPause={props.onPause}
        {...layout}
      />
    );
  }

  if (props.mode === "multi") {
    return (
      <MultiUploadStatus
        phase={props.phase}
        files={props.files}
        totalProgress={props.totalProgress}
        error={props.error}
        onCancel={props.onCancel}
        {...layout}
      />
    );
  }

  return (
    <UploadStatus
      phase={props.phase}
      progress={props.progress}
      error={props.error}
      fileInfo={props.fileInfo}
      onCancel={props.onCancel}
      onPause={props.onPause}
      {...layout}
    />
  );
}

"use client";

import type { ReactNode } from "react";
import { AlertCircleIcon, PauseIcon, XIcon } from "lucide-react";
import {
  formatFileSize,
  truncateFileName,
  type DimahS3Error,
} from "@dimah-s3/core";
import { useFormatDimahError } from "@dimah-s3/react";
import { useTranslations } from "@fuma-translate/react";
import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";
import { CircleProgress } from "@/registry/dimah-s3-ui/components/dimah-s3/attachment/circle-progress";
import {
  ATTACHMENT_ERROR_DESCRIPTION_CLASS,
  ATTACHMENT_TITLE_CLASS,
  type AttachmentOrientation,
  type AttachmentSize,
  type AttachmentState,
} from "@/registry/dimah-s3-ui/lib/attachment";
import { FileTypeGlyph } from "@/registry/dimah-s3-ui/lib/file-type-icon";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

const PROGRESS_BY_SIZE = {
  default: { size: 20, strokeWidth: 2.5, className: "size-5" },
  sm: { size: 16, strokeWidth: 2, className: "size-4" },
  xs: { size: 14, strokeWidth: 1.5, className: "size-3.5" },
} as const satisfies Record<
  AttachmentSize,
  { size: number; strokeWidth: number; className: string }
>;

export type FileAttachmentProps = {
  /** @default "sm" */
  size?: AttachmentSize;
  /** @default "horizontal" */
  orientation?: AttachmentOrientation;
  state: AttachmentState;
  fileName: string;
  fileSize?: number;
  /** MIME type — used with the filename to pick a type icon when no preview. */
  fileType?: string | null;
  /** Image thumbnail URL — enables `AttachmentMedia variant="image"`. */
  previewUrl?: string | null;
  /** Progress 0–100 when `state` is uploading/idle (pending). */
  percent?: number;
  /** Secondary line; defaults to size, or error text when `state="error"`. */
  description?: ReactNode;
  error?: string | DimahS3Error | null;
  onCancel?: () => void;
  onPause?: () => void;
  className?: string;
};

export function FileAttachment({
  state,
  fileName,
  fileSize,
  fileType,
  previewUrl,
  percent = 0,
  description,
  error,
  onCancel,
  onPause,
  size = "sm",
  orientation = "horizontal",
  className,
}: FileAttachmentProps) {
  const t = useTranslations();
  const formatError = useFormatDimahError();
  const errorText =
    error == null
      ? null
      : typeof error === "string"
        ? error
        : formatError(error);
  const hasPreview = Boolean(previewUrl);
  const progress = PROGRESS_BY_SIZE[size];

  const resolvedDescription =
    description ??
    (state === "error"
      ? (errorText ?? t("Upload failed", { note: "status" }))
      : fileSize != null
        ? formatFileSize(fileSize)
        : null);

  const showActions =
    (state === "uploading" || state === "processing") &&
    (onCancel != null || onPause != null);

  const showProgressOverlay =
    state === "uploading" || state === "processing" || state === "idle";

  const mediaOverlay = showProgressOverlay ? (
    <div className="absolute inset-0 flex items-center justify-center bg-dimah-s3-background/60">
      <CircleProgress
        percent={state === "uploading" ? percent : 0}
        size={progress.size}
        strokeWidth={progress.strokeWidth}
        className={progress.className}
      />
    </div>
  ) : state === "error" ? (
    <div className="absolute inset-0 flex items-center justify-center bg-dimah-s3-destructive/20 text-dimah-s3-destructive">
      <AlertCircleIcon />
    </div>
  ) : null;

  return (
    <Attachment
      state={state}
      size={size}
      orientation={orientation}
      className={cn(
        orientation === "horizontal" && "w-full max-w-full",
        className,
      )}
    >
      {hasPreview ? (
        <AttachmentMedia variant="image">
          <img src={previewUrl!} alt="" />
          {mediaOverlay}
        </AttachmentMedia>
      ) : (
        <AttachmentMedia>
          <FileTypeGlyph fileName={fileName} fileType={fileType} />
          {mediaOverlay}
        </AttachmentMedia>
      )}
      <AttachmentContent>
        <AttachmentTitle className={ATTACHMENT_TITLE_CLASS}>
          {truncateFileName(fileName)}
        </AttachmentTitle>
        {resolvedDescription != null ? (
          <AttachmentDescription
            className={
              state === "error" ? ATTACHMENT_ERROR_DESCRIPTION_CLASS : undefined
            }
          >
            {resolvedDescription}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {showActions ? (
        <AttachmentActions>
          {onPause ? (
            <AttachmentAction
              aria-label={t("Pause", { note: "upload control" })}
              onClick={(e) => {
                e.stopPropagation();
                onPause();
              }}
            >
              <PauseIcon />
            </AttachmentAction>
          ) : null}
          {onCancel ? (
            <AttachmentAction
              aria-label={t("Cancel", { note: "upload control" })}
              onClick={(e) => {
                e.stopPropagation();
                onCancel();
              }}
            >
              <XIcon />
            </AttachmentAction>
          ) : null}
        </AttachmentActions>
      ) : null}
    </Attachment>
  );
}

"use client";

import { cn } from "@/registry/dimah-s3-ui/lib/utils";

export function CircleProgress({
  percent,
  size = 20,
  strokeWidth = 2.5,
  className,
}: {
  percent: number;
  size?: number;
  strokeWidth?: number;
  className?: string;
}) {
  const r = (size - strokeWidth) / 2;
  const c = 2 * Math.PI * r;
  const offset = c - (percent / 100) * c;
  return (
    <svg
      width={size}
      height={size}
      className={cn("shrink-0 -rotate-90", className)}
      style={{ width: size, height: size }}
      aria-hidden
    >
      <circle
        cx={size / 2}
        cy={size / 2}
        r={r}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        className="text-dimah-s3-muted-foreground/60"
      />
      <circle
        cx={size / 2}
        cy={size / 2}
        r={r}
        fill="none"
        stroke="currentColor"
        strokeWidth={strokeWidth}
        strokeDasharray={c}
        strokeDashoffset={offset}
        strokeLinecap="round"
        className="text-dimah-s3-primary transition-[stroke-dashoffset] duration-200"
      />
    </svg>
  );
}

"use client";

import { useEffect, useLayoutEffect, useRef } from "react";
import { formatFileSize } from "@dimah-s3/core";
import { useTranslations } from "@fuma-translate/react";
import { useFormatDimahError } from "@dimah-s3/react";
import type {
  DimahS3Error,
  UploadFileInfo,
  UploadProgress,
  MultiUploadFileState,
} from "@dimah-s3/react";

import { toast } from "@/components/ui/toast";

export type UploadToastCtrl = {
  mode: "single" | "multi";
  phase: string;
  fileInfo?: UploadFileInfo | null;
  progress?: UploadProgress;
  files?: MultiUploadFileState[];
  totalProgress?: UploadProgress;
  error: DimahS3Error | null;
  cancel: () => void;
};

function sizeNode(size: number) {
  return (
    <span dir="ltr" className="inline-block whitespace-nowrap tabular-nums">
      {formatFileSize(size)}
    </span>
  );
}

function progressNode(loaded: number, total: number) {
  return (
    <span dir="ltr" className="inline-block whitespace-nowrap tabular-nums">
      {formatFileSize(loaded)} / {formatFileSize(total)}
    </span>
  );
}

/**
 * Drives toasts for upload progress/success/error.
 * Shared between UploadButton and UploadDropzone.
 */
export function useUploadToast(ctrl: UploadToastCtrl, enabled: boolean) {
  const t = useTranslations();
  const formatError = useFormatDimahError();
  const toastIdRef = useRef<string | null>(null);
  const prevPhaseRef = useRef(ctrl.phase);
  const cancelRef = useRef(ctrl.cancel);
  useLayoutEffect(() => {
    cancelRef.current = ctrl.cancel;
  });

  const { mode, phase, fileInfo, progress, files, totalProgress, error } = ctrl;

  // Phase-transition toasts (once per phase change)
  useEffect(() => {
    if (prevPhaseRef.current === phase) return;
    prevPhaseRef.current = phase;
    if (!enabled) return;

    const fileList = files ?? [];
    const isMulti = mode === "multi" && fileList.length > 1;
    const file =
      fileInfo ??
      (fileList.length === 1
        ? { name: fileList[0].fileName, size: fileList[0].fileSize }
        : null);
    const total = totalProgress?.total ?? 0;

    if (phase === "idle" && toastIdRef.current) {
      toast.close(toastIdRef.current);
      toastIdRef.current = null;
    }
    if (phase === "success") {
      if (toastIdRef.current) toast.close(toastIdRef.current);
      if (isMulti) {
        toast.add({
          type: "success",
          title: t("{count} file(s) uploaded", {
            note: "toast",
            variables: { count: String(fileList.length) },
          }),
          description: sizeNode(total),
        });
      } else if (file) {
        toast.add({
          type: "success",
          title: t("Upload complete", { note: "toast" }),
          description: sizeNode(file.size),
        });
      }
      toastIdRef.current = null;
    }
    if (phase === "error") {
      if (toastIdRef.current) toast.close(toastIdRef.current);
      if (isMulti && fileList.length > 0) {
        const succeeded = fileList.filter((f) => f.status === "success").length;
        const failed = fileList.filter((f) => f.status === "error").length;
        toast.add({
          type: "error",
          title: t("Upload finished with errors", { note: "toast" }),
          description: (
            <span
              dir="ltr"
              className="inline-block whitespace-nowrap tabular-nums"
            >
              {t("{succeeded} succeeded, {failed} failed", {
                note: "toast",
                variables: {
                  succeeded: String(succeeded),
                  failed: String(failed),
                },
              })}
            </span>
          ),
        });
      } else {
        toast.add({
          type: "error",
          title: t("Upload failed", { note: "toast" }),
          description: (
            <span dir="auto" className="block [overflow-wrap:anywhere]">
              {error
                ? formatError(error)
                : fileList[0]?.error
                  ? formatError(fileList[0].error)
                  : t("Unknown error", { note: "fallback" })}
            </span>
          ),
        });
      }
      toastIdRef.current = null;
    }
  }, [
    enabled,
    phase,
    mode,
    fileInfo,
    files,
    totalProgress,
    error,
    t,
    formatError,
  ]);

  // Progress toast (updated on each progress tick)
  useEffect(() => {
    if (!enabled || phase !== "uploading") return;

    const fileList = files ?? [];
    const isMulti = mode === "multi" && fileList.length > 1;
    const file =
      fileInfo ??
      (fileList.length === 1
        ? { name: fileList[0].fileName, size: fileList[0].fileSize }
        : null);
    const total = totalProgress ?? { loaded: 0, total: 0, percent: 0 };
    const singleProgress =
      progress ??
      (fileList.length === 1
        ? fileList[0].progress
        : { loaded: 0, total: 0, percent: 0 });

    const payload = isMulti
      ? {
          type: "loading" as const,
          timeout: 0,
          title: t("Uploading {done}/{total}", {
            note: "toast",
            variables: {
              done: String(
                fileList.filter((f) => f.status === "success").length,
              ),
              total: String(fileList.length),
            },
          }),
          description: progressNode(total.loaded, total.total),
          actionProps: {
            children: t("Cancel", { note: "toast action" }),
            onClick: () => cancelRef.current(),
          },
        }
      : file
        ? {
            type: "loading" as const,
            timeout: 0,
            title: t("Uploading", { note: "toast" }),
            description: progressNode(singleProgress.loaded, file.size),
            actionProps: {
              children: t("Cancel", { note: "toast action" }),
              onClick: () => cancelRef.current(),
            },
          }
        : null;

    if (!payload) return;

    if (toastIdRef.current) {
      toast.update(toastIdRef.current, payload);
    } else {
      toastIdRef.current = toast.add(payload);
    }
  }, [enabled, phase, mode, fileInfo, files, progress, totalProgress, t]);
}

"use client";

import type { ReactNode } from "react";
import {
  AlertCircleIcon,
  CheckCircleIcon,
  LoaderCircleIcon,
} from "lucide-react";
import {
  Attachment,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentTitle,
} from "@/registry/dimah-s3-ui/components/ui/attachment";
import {
  ATTACHMENT_ERROR_DESCRIPTION_CLASS,
  ATTACHMENT_TITLE_CLASS,
  type AttachmentOrientation,
  type AttachmentSize,
  type AttachmentState,
} from "@/registry/dimah-s3-ui/lib/attachment";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

export type StatusAttachmentProps = {
  /** @default "sm" */
  size?: AttachmentSize;
  /** @default "horizontal" */
  orientation?: AttachmentOrientation;
  state: AttachmentState;
  title?: ReactNode;
  description?: ReactNode;
  media?: ReactNode;
  actions?: ReactNode;
  className?: string;
};

/**
 * Minimal Attachment shell for operation feedback (upload/download/delete).
 * Relies on Attachment `data-state` styles for error/done chrome.
 */
export function StatusAttachment({
  state,
  title,
  description,
  media,
  actions,
  size = "sm",
  orientation = "horizontal",
  className,
}: StatusAttachmentProps) {
  const defaultMedia =
    state === "error" ? (
      <AlertCircleIcon />
    ) : state === "done" ? (
      <CheckCircleIcon />
    ) : state === "processing" || state === "uploading" ? (
      <LoaderCircleIcon className="animate-spin" data-slot="spinner" />
    ) : null;

  return (
    <Attachment
      state={state}
      size={size}
      orientation={orientation}
      className={cn(
        orientation === "horizontal" && "w-full max-w-full",
        className,
      )}
    >
      <AttachmentMedia>{media ?? defaultMedia}</AttachmentMedia>
      <AttachmentContent>
        {title != null ? (
          <AttachmentTitle className={ATTACHMENT_TITLE_CLASS}>
            {title}
          </AttachmentTitle>
        ) : null}
        {description != null ? (
          <AttachmentDescription
            className={
              state === "error" ? ATTACHMENT_ERROR_DESCRIPTION_CLASS : undefined
            }
          >
            {description}
          </AttachmentDescription>
        ) : null}
      </AttachmentContent>
      {actions ? <AttachmentActions>{actions}</AttachmentActions> : null}
    </Attachment>
  );
}

import type { ComponentProps, ReactNode } from "react";
import { Attachment } from "@/registry/dimah-s3-ui/components/ui/attachment";

/**
 * Attachment layout/state types — derived from stock shadcn {@link Attachment}
 * (do not edit `components/ui/attachment.tsx`).
 */
export type AttachmentState = NonNullable<
  ComponentProps<typeof Attachment>["state"]
>;

export type AttachmentSize = NonNullable<
  ComponentProps<typeof Attachment>["size"]
>;

export type AttachmentOrientation = NonNullable<
  ComponentProps<typeof Attachment>["orientation"]
>;

/** `size` / `orientation` forwarded onto stock `Attachment`. */
export type AttachmentLayoutProps = {
  size?: AttachmentSize;
  orientation?: AttachmentOrientation;
};

/**
 * Wired button/dropzone aliases — avoids clashing with Button `size`.
 * Maps to {@link AttachmentLayoutProps} on status rows.
 */
export type AttachmentLayoutAliases = {
  /** Attachment size (not the trigger button size). @default "sm" */
  attachmentSize?: AttachmentSize;
  /** Attachment orientation. @default "horizontal" */
  attachmentOrientation?: AttachmentOrientation;
};

/** Error description: allow wrap past truncate (AttachmentDescription default). */
export const ATTACHMENT_ERROR_DESCRIPTION_CLASS =
  "overflow-visible whitespace-normal [overflow-wrap:anywhere]";

/**
 * Title layout + dark-only shimmer highlight.
 * Stock `shimmer` brightens `currentColor` in dark mode; near-white titles
 * (typical `card-foreground`) make that band invisible. Override highlight
 * only in dark via the official `shimmer-color-*` utility + theme token —
 * leave light mode on the stock formula.
 */
export const ATTACHMENT_TITLE_CLASS =
  "max-w-[48ch] dark:shimmer-color-dimah-s3-muted-foreground";

/**
 * Controls inline status rendering for wired UI components.
 *
 * - `true` (default): render the status node in the default slot
 * - `false`: hide status
 * - `(node) => ReactNode`: wrap or relocate the status node
 */
export type StatusSlot = boolean | ((node: ReactNode) => ReactNode);

/** Resolve a {@link StatusSlot} against a built status node. */
export function resolveStatusSlot(
  slot: StatusSlot = true,
  node: ReactNode,
): ReactNode {
  if (slot === false) return null;
  if (typeof slot === "function") return slot(node);
  return node;
}

"use client";

import { FileIcon, defaultStyles } from "react-file-icon";
import type { DefaultExtensionType, FileIconProps } from "react-file-icon";
import { cn } from "@/registry/dimah-s3-ui/lib/utils";

/**
 * Curated extensions with colored glyphs via `react-file-icon`.
 * Keep this list lean — duplicates and rare types belong in aliases / MIME
 * family fallbacks, not here. Unknown types use a neutral generic file icon.
 */
const CURATED_EXTS = [
  // documents
  "pdf",
  "doc",
  "docx",
  "txt",
  "md",
  // sheets / slides
  "xls",
  "xlsx",
  "csv",
  "ppt",
  "pptx",
  // archives
  "zip",
  "rar",
  "7z",
  "tar",
  "gz",
  // audio / video
  "mp3",
  "wav",
  "m4a",
  "mp4",
  "mov",
  "webm",
  "mkv",
  // images
  "png",
  "jpg",
  "gif",
  "webp",
  "svg",
  "heic",
  // code / data
  "json",
  "js",
  "ts",
  "jsx",
  "html",
  "css",
] as const;

type CuratedExt = (typeof CURATED_EXTS)[number];

const CURATED = new Set<string>(CURATED_EXTS);

/**
 * Map alternate extensions onto a curated key (same glyph, no list bloat).
 * Also remaps `defaultStyles` keys that differ from the real extension.
 */
const EXT_ALIASES: Record<string, CuratedExt | DefaultExtensionType> = {
  jpeg: "jpg",
  jpe: "jpg",
  "7zip": "7z",
  m4v: "mp4",
  aac: "m4a",
  flac: "mp3",
  ogg: "mp3",
  avi: "mp4",
  bmp: "png",
  tif: "png",
  tiff: "png",
};

/** `defaultStyles` lookup when the curated key differs from the library key. */
const STYLE_ALIASES: Record<string, DefaultExtensionType> = {
  "7z": "7zip",
};

const MIME_TO_EXT: Record<string, CuratedExt> = {
  "application/pdf": "pdf",
  "application/msword": "doc",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document":
    "docx",
  "application/vnd.ms-excel": "xls",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
  "text/csv": "csv",
  "application/vnd.ms-powerpoint": "ppt",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation":
    "pptx",
  "application/zip": "zip",
  "application/x-zip-compressed": "zip",
  "application/x-rar-compressed": "rar",
  "application/vnd.rar": "rar",
  "application/x-7z-compressed": "7z",
  "application/x-tar": "tar",
  "application/gzip": "gz",
  "audio/mpeg": "mp3",
  "audio/wav": "wav",
  "audio/mp4": "m4a",
  "audio/aac": "m4a",
  "video/mp4": "mp4",
  "video/quicktime": "mov",
  "video/webm": "webm",
  "video/x-matroska": "mkv",
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/gif": "gif",
  "image/webp": "webp",
  "image/svg+xml": "svg",
  "image/heic": "heic",
  "application/json": "json",
  "text/javascript": "js",
  "application/javascript": "js",
  "text/typescript": "ts",
  "application/typescript": "ts",
  "text/jsx": "jsx",
  "text/html": "html",
  "text/css": "css",
  "text/plain": "txt",
  "text/markdown": "md",
};

function extensionOf(fileName: string): string | null {
  const base = fileName.split(/[/\\]/).pop() ?? fileName;
  const dot = base.lastIndexOf(".");
  if (dot <= 0 || dot === base.length - 1) return null;
  return base.slice(dot + 1).toLowerCase();
}

function mimeFamilyExt(mime: string): CuratedExt | null {
  if (mime.startsWith("image/")) return "png";
  if (mime.startsWith("audio/")) return "mp3";
  if (mime.startsWith("video/")) return "mp4";
  if (mime.startsWith("text/")) return "txt";
  return null;
}

function normalizeExt(ext: string): CuratedExt | null {
  if (CURATED.has(ext)) return ext as CuratedExt;
  const aliased = EXT_ALIASES[ext];
  if (aliased && CURATED.has(aliased)) return aliased as CuratedExt;
  return null;
}

/** Resolve a curated extension key for icon styling (or `null` if unknown). */
export function resolveFileTypeExtension(
  fileName: string,
  mimeType?: string | null,
): string | null {
  const mime = mimeType?.trim().toLowerCase();
  if (mime) {
    const fromMime = MIME_TO_EXT[mime];
    if (fromMime) return fromMime;
    const family = mimeFamilyExt(mime);
    if (family) return family;
  }

  const ext = extensionOf(fileName);
  if (!ext) return null;
  return normalizeExt(ext);
}

function stylesFor(ext: string): Partial<FileIconProps> {
  const key = (STYLE_ALIASES[ext] ?? ext) as DefaultExtensionType;
  const fromDefaults = defaultStyles[key];
  if (fromDefaults) return fromDefaults;
  // `heic` may be missing from older @types; keep a sensible image style.
  if (ext === "heic") return { type: "image" };
  if (ext === "7z") return { type: "compressed" };
  return {};
}

export type FileTypeGlyphProps = {
  fileName: string;
  fileType?: string | null;
  className?: string;
};

/**
 * Colored file glyph for attachment media (no image preview).
 * Uses `react-file-icon` + a lean curated extension map.
 */
export function FileTypeGlyph({
  fileName,
  fileType,
  className,
}: FileTypeGlyphProps) {
  const ext = resolveFileTypeExtension(fileName, fileType);
  const label = ext ?? extensionOf(fileName) ?? undefined;
  const styles = ext ? stylesFor(ext) : { type: "document" as const };

  return (
    <span
      className={cn(
        // Fill the media box so the glyph tracks Attachment size/orientation
        // (vertical media can grow well past the default icon rem sizes).
        "flex size-full items-center justify-center [&_svg]:size-[min(76%,8rem)]!",
        className,
      )}
      aria-hidden
    >
      <FileIcon extension={label} {...styles} />
    </span>
  );
}
